-- migration_026_new_questions_sept2026k.sql
-- Batch 11 of new questions from "questions to add.pdf" (Clinical Pain, Pharmacology, Physics):
--   q_sba_gout_colchicine_cardiovascular_001 (SBA, Clinical Pain) -- new knowledge box "Gout"
--     (diagnosis, acute management + first-line option comparison table, colchicine, what not
--     to do in a flare, long-term management, NICE NG219 button inside the box)
--     + relevantReading (NICE NG219, GPnotebook)
--   q_sba_baclofen_renal_excretion_half_life_001 (SBA, Pharmacology) -- new knowledge box
--     "Baclofen" + new images/baclofen-gabab-mechanism.svg + relevantReading (PMC review)
--   q_sba_gabapentin_renal_excretion_half_life_001 (SBA, Pharmacology) -- new knowledge box
--     "Gabapentinoids" + new images/gabapentinoid-a2d-mechanism.svg
--   q_sba_scs_crps_outcome_factor_001 (SBA, Physics & Clinical Measurement) -- new knowledge box
--     "Spinal Cord Stimulation (SCS) -- Indications" with the NICE TA159 button inside the box
--     + relevantReading (SCS e-tool, British Pain Society)
--
-- Retroactive edits (PDF: "add this knowledge summary to any other question related to gout" /
-- "add also to any question about gabapentin/pregabalin"):
--   q_sba_gout_diagnosis_001, q_sba_gout_flare_treatment_001 -- standalone NG219 button replaced
--     by the shared "Gout" knowledge box (which contains the same button) + gout relevantReading
--   q_gabapentin_001 -- shared "Gabapentinoids" knowledge box appended
-- Shared boxes are byte-identical across questions so knowledge-summary.html dedupes them.
--
-- The 3 retroactive updates overwrite 'explanation' (and 'relevantReading' for gout) with the
-- full current text from questions.json, so re-running is safe.
-- No new categories.

-- ===== New questions =====
insert into questions (id, type, data, status) values ('q_sba_gout_colchicine_cardiovascular_001', 'SBA', '{"dateAdded":"2026-09-30","rotationIndex":126,"question":"A 60-year-old man with a history of atrial fibrillation and ischaemic heart disease presents with a 1-week history of severe pain, swelling and redness of the right first metatarsophalangeal joint. Joint aspirate shows crystals, with no evidence of bacterial infection. What is the most appropriate treatment for this patient?","choices":["Allopurinol","Colchicine","Diclofenac","Paracetamol","Opioids"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">This patient has an acute gout flare (crystals on aspirate, infection excluded). NSAIDs and colchicine are both first-line treatments for an acute attack, but his <strong>atrial fibrillation and ischaemic heart disease</strong> are significant relative contraindications to NSAID use. Given these comorbidities, <strong>colchicine</strong> becomes the preferred first-line option for the acute flare.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Allopurinol is a urate-lowering therapy for long-term prophylaxis and is <strong>not indicated during an acute flare</strong> &mdash; starting it now could prolong or worsen the attack. It should only be considered once the acute episode has resolved, regardless of his cardiovascular history.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> With NSAIDs relatively contraindicated by his cardiovascular disease, colchicine is the most appropriate first-line treatment for this acute gout flare, avoiding the cardiovascular and bleeding risks associated with NSAID use in this comorbidity profile.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> NSAIDs, including diclofenac, are associated with an <strong>increased risk of cardiovascular thrombotic events</strong> and are generally avoided in patients with established ischaemic heart disease. NSAIDs also increase bleeding risk if he is anticoagulated for his AF, and diclofenac carries one of the higher cardiovascular risk profiles among NSAIDs &mdash; making it an inappropriate first choice here.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Paracetamol is a simple analgesic with minimal anti-inflammatory action &mdash; inadequate as monotherapy for the intense inflammatory pain of an acute gout flare, regardless of his comorbidities.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Opioids do not address the underlying inflammatory process and offer no advantage over an appropriately chosen anti-inflammatory agent in this context. Unnecessary opioid exposure should be avoided when a more targeted, effective treatment (colchicine) is available and appropriate.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Gout</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnosis</div><table style=\"margin:0\"><tr><th>Clinical presentation</th><td>Acute, severe <strong>monoarticular</strong> pain, swelling, erythema and warmth &mdash; classically the <strong>first metatarsophalangeal (MTP) joint</strong></td></tr><tr><th>Definitive diagnosis</th><td>Joint aspiration with <strong>polarised light microscopy</strong>: needle-shaped, <strong>negatively birefringent</strong> monosodium urate crystals</td></tr><tr><th>Excluding sepsis</th><td>The aspirate is also sent for Gram stain and culture to exclude <strong>septic arthritis</strong></td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Management of Acute Gout</div><table style=\"margin:0\"><tr><th>First-line (equal options)</th><td>An <strong>NSAID</strong>, <strong>colchicine</strong>, or a <strong>short course of oral corticosteroid</strong> &mdash; chosen according to comorbidities, co-prescriptions and patient preference (oral corticosteroids are used <em>off-label</em> for this indication)</td></tr><tr><th>If taking an NSAID</th><td>Consider adding a <strong>proton pump inhibitor (PPI)</strong></td></tr><tr><th>If NSAIDs and colchicine are contraindicated, not tolerated or ineffective</th><td>Consider an <strong>intra-articular or intramuscular corticosteroid injection</strong> (off-label)</td></tr><tr><th>Adjunct</th><td><strong>Ice packs</strong> applied to the joint, alongside prescribed medicine, may help relieve pain</td></tr></table><table style=\"margin:12px 0 0\"><tr><th>First-line option</th><th>Favour when</th><th>Avoid / caution when</th></tr><tr><td><strong>NSAID</strong></td><td>No cardiovascular, renal or GI contraindications</td><td>Ischaemic heart disease, heart failure, renal impairment, peptic ulcer disease, anticoagulation</td></tr><tr><td><strong>Colchicine</strong></td><td>NSAIDs contraindicated (e.g. cardiovascular disease)</td><td>Significant renal/hepatic impairment; interacting P-gp/CYP3A4 inhibitors</td></tr><tr><td><strong>Oral corticosteroid</strong></td><td>NSAIDs and colchicine both unsuitable</td><td>Poorly controlled diabetes; infection not yet excluded</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Colchicine</div><table style=\"margin:0\"><tr><th>Main side effect</th><td><strong>Dose-dependent gastrointestinal upset</strong> (diarrhoea, nausea, vomiting) &mdash; often the limiting factor for tolerability</td></tr><tr><th>Dose adjustment</th><td>Requires <strong>dose reduction in renal and hepatic impairment</strong></td></tr><tr><th>Drug interactions</th><td><strong>P-glycoprotein and CYP3A4 inhibitors</strong> (e.g. clarithromycin, ciclosporin, some antifungals) can significantly increase colchicine levels and toxicity risk</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Relevant in patients with atrial fibrillation: verapamil, diltiazem and amiodarone are also P-glycoprotein/CYP3A4 inhibitors, so check the drug history and reduce the colchicine dose if they are co-prescribed.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">What NOT to Do During an Acute Flare</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Do <strong>not start</strong> urate-lowering therapy (allopurinol, febuxostat) during an acute attack</td></tr><tr><td>Do <strong>not stop</strong> urate-lowering therapy if already established &mdash; continue it alongside acute treatment</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Long-term / Prophylactic Management (Once the Flare Has Settled)</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td><strong>Allopurinol</strong> (first-line) or <strong>febuxostat</strong>, titrated to a target serum urate</td></tr><tr><td>Lifestyle modification: weight loss, reduced alcohol and purine intake, adequate hydration</td></tr><tr><td>Cover with <strong>low-dose colchicine or an NSAID</strong> when initiating urate-lowering therapy to reduce the risk of flares</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><button type=\"button\" class=\"nice-guideline-btn\" onclick=\"openGuidelineModal(''ng219'',''NICE NG219 — Gout'')\">\n  <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"9\" y1=\"13\" x2=\"15\" y2=\"13\"/><line x1=\"9\" y1=\"17\" x2=\"15\" y2=\"17\"/></svg>\n  NICE NG219 &mdash; Gout Summary\n</button></div></div>\n</div></div>","relevantReading":[{"label":"Gout: diagnosis and management (NG219)","source":"NICE","url":"https://www.nice.org.uk/guidance/ng219"},{"label":"Gout","source":"GPnotebook","url":"https://gpnotebook.com/en-GB/pages/rheumatology/gout"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_baclofen_renal_excretion_half_life_001', 'SBA', '{"dateAdded":"2026-09-30","rotationIndex":127,"question":"A drug is excreted predominantly unchanged by the kidney and has a plasma half-life of approximately 3 hours. Which of the following drugs does this best describe?","choices":["Baclofen","Amitriptyline","Gabapentin","Morphine","Ketamine"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Two features narrow the options: <strong>predominantly renal excretion of unchanged drug</strong>, and a <strong>short half-life of around 3 hours</strong>. Baclofen fits both. Gabapentin shares the renal excretion but has a longer half-life, and the remaining options all undergo extensive hepatic metabolism.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> Baclofen, a GABA-B receptor agonist used in pain medicine for spasticity-associated pain (and as intrathecal therapy for severe spasticity), undergoes <strong>minimal hepatic metabolism</strong>, with approximately <strong>70&ndash;85% excreted unchanged by the kidney</strong>. Its plasma half-life is approximately <strong>2.5&ndash;4 hours</strong>, making renal function an important determinant of dosing and accumulation risk.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Amitriptyline is extensively <strong>hepatically metabolised</strong> (via CYP2D6/CYP1A2/CYP3A4) to nortriptyline and other metabolites, with a much <strong>longer</strong> half-life (10&ndash;28 hours) &mdash; it is not excreted unchanged and does not match the stated half-life.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Gabapentin is also excreted almost entirely unchanged by the kidney, but its half-life is longer, approximately <strong>5&ndash;7 hours</strong>.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Morphine undergoes extensive <strong>hepatic glucuronidation</strong> to active and inactive metabolites (M6G, M3G) &mdash; it is not excreted unchanged.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Ketamine undergoes hepatic metabolism via <strong>CYP3A4</strong> to norketamine, an active metabolite.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Baclofen</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification and Mechanism</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>GABA-B receptor agonist</strong>, acting presynaptically and postsynaptically at spinal and supraspinal levels.</p><table style=\"margin:12px 0 0\"><tr><th>Site</th><th>Effect of GABA-B activation</th></tr><tr><td><strong>Presynaptic</strong></td><td>Reduced <strong>calcium influx</strong> &rarr; decreased release of excitatory neurotransmitters (glutamate, aspartate, substance P) from primary afferent terminals</td></tr><tr><td><strong>Postsynaptic</strong></td><td><strong>Potassium channel opening</strong> &rarr; hyperpolarisation of motor neurones</td></tr><tr><td><strong>Net effect</strong></td><td>Reduced excitatory transmission at the spinal cord level &rarr; muscle relaxation and reduced spasticity, with some analgesic effect (particularly relevant to spasticity-associated pain)</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/baclofen-gabab-mechanism.svg\" alt=\"Baclofen activates presynaptic GABA-B receptors to reduce calcium influx and excitatory neurotransmitter release, and postsynaptic GABA-B receptors to open potassium channels and hyperpolarise the neurone\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pharmacokinetics</div><table style=\"margin:0\"><tr><th>Metabolism</th><td>Minimal hepatic metabolism (~15%)</td></tr><tr><th>Excretion</th><td><strong>70&ndash;85% excreted unchanged by the kidney</strong></td></tr><tr><th>Half-life</th><td><strong>2.5&ndash;4 hours</strong> (commonly cited as ~3 hours)</td></tr><tr><th>Oral bioavailability</th><td>Variable and dose-dependent</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Because baclofen depends on renal excretion, it accumulates in renal impairment &mdash; causing confusion and sedation, particularly in the elderly. Compare gabapentin: also excreted unchanged by the kidney, but with a longer half-life of 5&ndash;7 hours.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Routes of Administration</div><table style=\"margin:0\"><tr><th>Oral</th><td>Generalised spasticity (e.g. multiple sclerosis, spinal cord injury)</td></tr><tr><th>Intrathecal (ITB)</th><td>Severe, refractory spasticity unresponsive to oral therapy, or where oral doses cause unacceptable systemic side effects (sedation, weakness). Delivered via an <strong>implanted pump</strong> directly into the intrathecal space, achieving effective spinal concentrations at much lower total doses than oral administration</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Uses</div><table style=\"margin:0\"><tr><th>Indication</th></tr><tr><td>Spasticity of cerebral or spinal origin (multiple sclerosis, spinal cord injury, cerebral palsy, traumatic brain injury)</td></tr><tr><td>Off-label use in some chronic pain conditions with a spasticity component</td></tr><tr><td><strong>Intrathecal baclofen</strong> specifically for severe spasticity refractory to oral antispasmodics</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Side Effects</div><table style=\"margin:0\"><tr><th>Side effect</th></tr><tr><td>Sedation, drowsiness, dizziness</td></tr><tr><td>Muscle weakness / hypotonia</td></tr><tr><td>Nausea</td></tr><tr><td>Confusion (particularly in elderly patients, or with accumulation in renal impairment)</td></tr><tr><td>Lowered seizure threshold in susceptible patients</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Withdrawal &mdash; A Critical Safety Issue</div><table style=\"margin:0\"><tr><th>Triggers</th><td>Abrupt cessation of oral baclofen, or interruption of intrathecal delivery (pump failure, catheter dislodgement/occlusion, empty reservoir)</td></tr><tr><th>Onset</th><td>Because of the short half-life, withdrawal can develop <strong>quickly and progress rapidly</strong></td></tr><tr><th>Features</th><td>Rebound spasticity/rigidity, <strong>high fever</strong>, altered mental status, autonomic instability &mdash; progressing to rhabdomyolysis, multi-organ failure and death if unrecognised and untreated</td></tr><tr><th>Management</th><td>A <strong>medical emergency</strong>: oral/enteral baclofen as an interim bridge, benzodiazepines for symptom control, and urgent restoration of intrathecal delivery</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Overdose</div><table style=\"margin:0\"><tr><th>Features</th><td>CNS depression, respiratory depression, hypotension, bradycardia, seizures, coma</td></tr><tr><th>Management</th><td>Largely supportive &mdash; <strong>no specific reversal agent</strong></td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Baclofen therapeutics, toxicity, and withdrawal: a narrative review","source":"PMC","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8182184/"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_gabapentin_renal_excretion_half_life_001', 'SBA', '{"dateAdded":"2026-09-30","rotationIndex":128,"question":"A drug is excreted almost entirely unchanged by the kidney and has a plasma half-life of approximately 6 hours. Which of the following drugs does this best describe?","choices":["Baclofen","Gabapentin","Amitriptyline","Methadone","Diclofenac"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Gabapentin undergoes <strong>negligible hepatic metabolism</strong> and is excreted almost entirely <strong>unchanged by the kidney</strong>, with a plasma half-life of approximately <strong>5&ndash;7 hours</strong>. Baclofen is the key distractor: it is also renally excreted, but its half-life is shorter.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Baclofen is also excreted predominantly unchanged by the kidney, making it a plausible distractor, but its half-life is shorter &mdash; approximately <strong>2.5&ndash;4 hours</strong> (commonly cited as ~3 hours) &mdash; and does not match the 6-hour figure given.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> Gabapentin, a gabapentinoid used for neuropathic pain, undergoes <strong>negligible hepatic metabolism</strong> and is excreted almost entirely <strong>unchanged by the kidney</strong>. Its plasma half-life is approximately <strong>6 hours</strong>, necessitating dose reduction in renal impairment.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Amitriptyline is extensively <strong>hepatically metabolised</strong> (via CYP2D6/CYP1A2/CYP3A4) to nortriptyline and other metabolites, with a much <strong>longer</strong> half-life (10&ndash;28 hours).</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Methadone is extensively <strong>hepatically metabolised</strong> (via CYP3A4/CYP2B6) to inactive metabolites, with a much <strong>longer and highly variable</strong> half-life (8&ndash;60+ hours).</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Diclofenac is an NSAID that is extensively <strong>hepatically metabolised</strong> (via CYP2C9), with a much <strong>shorter</strong> half-life (~1&ndash;2 hours).</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Gabapentinoids</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification and Mechanism</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Structurally related to GABA, but <strong>no direct action at GABA receptors</strong></td></tr><tr><td>Both bind to the <strong>alpha-2-delta (&alpha;2&delta;) subunit of presynaptic voltage-gated calcium channels</strong>, reducing calcium influx and the subsequent release of excitatory neurotransmitters (glutamate, noradrenaline, substance P) from presynaptic nerve terminals</td></tr><tr><td>Net effect: reduced neuronal excitability &mdash; anti-epileptic, analgesic and anxiolytic effects</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/gabapentinoid-a2d-mechanism.svg\" alt=\"Gabapentin and pregabalin bind the alpha-2-delta subunit of presynaptic voltage-gated calcium channels, reducing calcium influx and release of glutamate, noradrenaline and substance P, with no direct action at GABA receptors\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pharmacokinetics</div><table style=\"margin:0\"><tr><th>Feature</th><th>Gabapentin</th><th>Pregabalin</th></tr><tr><td>Hepatic metabolism</td><td>None</td><td>Negligible</td></tr><tr><td>Renal excretion</td><td>Almost entirely unchanged</td><td>Almost entirely unchanged</td></tr><tr><td>Half-life</td><td>5&ndash;7 hours</td><td>5&ndash;7 hours</td></tr><tr><td>Absorption / bioavailability</td><td><strong>Non-linear</strong> &mdash; saturable absorption via an L-amino acid transporter, so bioavailability falls as the dose rises</td><td><strong>Linear</strong> &mdash; dose-proportional plasma concentration</td></tr><tr><td>Typical dosing</td><td>Three times daily</td><td>Twice daily</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Both depend on renal excretion, so doses must be reduced in renal impairment.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Efficacy and Harm (Gabapentin)</div><table style=\"margin:0\"><tr><th>Measure</th><th>Outcome</th><th>Value</th></tr><tr><td><strong>NNT</strong></td><td>&ge;50% pain reduction in chronic neuropathic pain (overall)</td><td>~6&ndash;8</td></tr><tr><td><strong>NNH</strong></td><td>Minor side effects</td><td>4</td></tr><tr><td><strong>NNH</strong></td><td>Major side effects</td><td>12</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Uses</div><table style=\"margin:0\"><tr><th>Licensed in the UK</th><td>Gabapentin and pregabalin are both licensed for neuropathic pain; gabapentin is also licensed for partial seizures and postherpetic neuralgia specifically</td></tr><tr><th>Neuropathic pain</th><td>Painful diabetic neuropathy, postherpetic neuralgia, and other peripheral/central neuropathic pain</td></tr><tr><th>Pregabalin only</th><td>Additionally licensed for <strong>generalised anxiety disorder</strong> and as an adjunct for focal seizures</td></tr><tr><th>Perioperative use</th><td>Gabapentinoids reduce postoperative pain and opioid requirements, and reduce the incidence of vomiting, pruritus and urinary retention &mdash; but <strong>increase the risk of sedation</strong></td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Common Side Effects</div><table style=\"margin:0\"><tr><th>Side effect</th></tr><tr><td>Dizziness, somnolence/sedation, ataxia</td></tr><tr><td>Peripheral oedema, weight gain</td></tr><tr><td>Dry mouth, blurred vision</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Dependence and Misuse Potential</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Both <strong>reclassified as Class C, Schedule 3 controlled drugs</strong> in the UK (April 2019) because of recognised dependence and misuse potential</td></tr><tr><td>Withdrawal symptoms (insomnia, headache, nausea, anxiety, sweating) can occur on abrupt discontinuation &mdash; <strong>taper gradually</strong></td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_scs_crps_outcome_factor_001', 'SBA', '{"dateAdded":"2026-09-30","rotationIndex":129,"question":"Which of the following factors is most important for a successful outcome of spinal cord stimulator implantation for complex regional pain syndrome (CRPS)?","choices":["Accuracy of electrode placement","Duration from onset of symptoms to implantation","Distance between the electrodes","Choice of waveform","Type of implanted pulse generator (rechargeable vs non-rechargeable)"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Precise electrode placement &mdash; positioning the lead(s) within the epidural space so that the resulting paraesthesia (or, with paraesthesia-free paradigms, the therapeutic effect) reliably covers the specific painful area &mdash; is the <strong>single most important technical factor</strong> determining a successful outcome in spinal cord stimulation.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> Accurate electrode placement, ensuring reliable and reproducible coverage of the painful area, is the most critical determinant of a successful analgesic outcome.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> A recognised prognostic factor &mdash; <strong>earlier implantation</strong> (shorter duration of established CRPS before SCS) is generally associated with better outcomes, as prolonged untreated CRPS allows greater central sensitisation and secondary functional/psychological changes to become established. However, this is a <strong>patient/disease-related prognostic factor</strong> rather than a modifiable <strong>technical</strong> factor of the implantation procedure itself.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Electrode spacing is a relevant technical consideration in lead configuration, but it is a minor parameter compared with the overall accuracy of anatomical lead placement.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> The choice of waveform can influence the character and efficacy of stimulation, but it cannot compensate for a lead that has not been placed accurately.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> The type of pulse generator relates to device logistics, battery life and practical/cost considerations, but does not directly influence analgesic efficacy in the way that lead placement accuracy does.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Spinal Cord Stimulation (SCS) &mdash; Indications</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Established / Well-Recognised Indications</div><table style=\"margin:0\"><tr><th>Condition</th><th>Notes</th></tr><tr><td><strong>Failed back surgery syndrome</strong> (persistent spinal pain syndrome, type 2)</td><td>Historically the single most common indication; persistent radicular &plusmn; axial pain following spinal surgery</td></tr><tr><td><strong>Complex regional pain syndrome (CRPS)</strong>, types I and II</td><td>Particularly effective for limb-predominant pain; earlier implantation is associated with better outcomes</td></tr><tr><td><strong>Peripheral neuropathic pain</strong> (e.g. painful diabetic peripheral neuropathy)</td><td>Evidence supports use in painful diabetic neuropathy refractory to pharmacological management</td></tr><tr><td><strong>Refractory angina pectoris</strong></td><td>For patients without options for further revascularisation; works partly via a vascular/anti-ischaemic mechanism (vasodilatation), alongside pain modulation</td></tr><tr><td><strong>Critical limb ischaemia / peripheral vascular disease</strong></td><td>May improve pain and, in some studies, limb salvage/microcirculation in patients unsuitable for revascularisation. <strong>UK: NICE TA159 recommends SCS for ischaemic pain only in the context of research</strong></td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Other Recognised Indications (Less Common)</div><table style=\"margin:0\"><tr><th>Indication</th></tr><tr><td>Post-herniorrhaphy or other focal post-surgical neuropathic pain</td></tr><tr><td>Phantom limb pain</td></tr><tr><td>Painful peripheral nerve injury</td></tr><tr><td>Post-thoracotomy pain syndrome</td></tr><tr><td>Visceral pain syndromes (more limited evidence &mdash; e.g. chronic pancreatitis pain)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Prerequisites Before Considering SCS</div><table style=\"margin:0\"><tr><th>Prerequisite</th></tr><tr><td>Pain refractory to appropriate conservative and pharmacological management (multimodal analgesia, physiotherapy and psychological input trialled first)</td></tr><tr><td>Confirmed diagnosis appropriate to the underlying pathology (e.g. <strong>Budapest criteria</strong> for CRPS)</td></tr><tr><td>No significant untreated psychological comorbidity that would compromise outcome or the ability to engage with the device</td></tr><tr><td>Ongoing litigation/compensation claims are not the sole driver, and the patient has realistic expectations</td></tr><tr><td>Successful <strong>trial period</strong> with percutaneous leads (typically &ge;50% pain reduction) before proceeding to permanent implantation</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">NICE TA159 (2008) stipulates a successful trial before implantation, but the UK TRIAL-STIM study (2020) found that a screening trial did not improve outcomes, and many UK centres now offer a direct-to-implant pathway.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Contraindications</div><table style=\"margin:0\"><tr><th>Contraindication</th></tr><tr><td>Active local or systemic infection</td></tr><tr><td>Uncorrected coagulopathy / bleeding diathesis</td></tr><tr><td>Pregnancy (relative)</td></tr><tr><td>Cognitive impairment precluding safe use of the device or understanding of its programming</td></tr><tr><td>Significant untreated psychiatric illness</td></tr><tr><td>Anticipated future MRI scanning where MRI-conditional device considerations cannot be addressed (device-dependent)</td></tr><tr><td>Spinal canal stenosis or other pathology precluding safe lead placement at the required level</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Non-Indications / Limited Evidence</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td><strong>Nociceptive</strong> (rather than neuropathic) pain generally responds poorly to SCS</td></tr><tr><td><strong>Axial</strong> (non-radicular) low back pain alone has historically shown less consistent benefit than radicular leg pain, although newer waveforms have shown some improved efficacy for axial pain in more recent trials</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><button type=\"button\" class=\"nice-guideline-btn\" onclick=\"openGuidelineModal(''ta159'',''NICE TA159 &mdash; Spinal Cord Stimulation'')\">\n  <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"9\" y1=\"13\" x2=\"15\" y2=\"13\"/><line x1=\"9\" y1=\"17\" x2=\"15\" y2=\"17\"/></svg>\n  NICE TA159 &mdash; Spinal Cord Stimulation\n</button></div></div>\n</div></div>","relevantReading":[{"label":"SCS e-health tool: patient selection for spinal cord stimulation","source":"scstool.org","url":"https://www.scstool.org/"},{"label":"Spinal cord stimulation for the management of pain: recommendations for best clinical practice","source":"British Pain Society","url":"https://www.britishpainsociety.org/static/uploads/resources/files/book_scs_main_1.pdf"}]}'::jsonb, 'published')
  on conflict (id) do nothing;

